#ifndef VALIDATION_STUB_BIO_H
#define VALIDATION_STUB_BIO_H
#include <stdbool.h>
#include <stddef.h>

/* Minimal stand-ins for the kernel types used by drivers/xen/biomerge.c. */
struct page {
	unsigned long pfn;
};

struct bio_vec {
	struct page	*bv_page;
	unsigned int	bv_len;
	unsigned int	bv_offset;
};
#endif

#ifndef VALIDATION_STUB_XEN_PAGE_H
#define VALIDATION_STUB_XEN_PAGE_H
/* Mirror the target include chain: xen/page.h -> asm/xen/page.h -> linux/pfn.h.
 * PFN_DOWN and page_to_pfn/pfn_to_mfn are provided here so the real modified
 * source file can be compiled unchanged.
 */
#define PAGE_SHIFT 12
#define PFN_DOWN(x) ((x) >> PAGE_SHIFT)

struct page;
extern unsigned long test_pfn_to_mfn(unsigned long pfn);

static inline unsigned long page_to_pfn(struct page *page)
{
	return page->pfn;
}

static inline unsigned long pfn_to_mfn(unsigned long pfn)
{
	return test_pfn_to_mfn(pfn);
}
#endif

#include <stdio.h>
#include <linux/bio.h>
#include <xen/page.h>

/* The real, modified candidate implementation. */
bool xen_biovec_phys_mergeable(const struct bio_vec *vec1,
			       const struct bio_vec *vec2);

/* pfn -> mfn table filled by each scenario. */
static unsigned long mfn_table[16];
unsigned long test_pfn_to_mfn(unsigned long pfn)
{
	return mfn_table[pfn];
}

/* The pre-fix (vulnerable) expression, reproduced only to demonstrate that the
 * negative scenarios really triggered the original bug. It deliberately uses
 * the target's mfn identifiers.
 */
static bool old_mergeable(const struct bio_vec *vec1, const struct bio_vec *vec2)
{
	unsigned long mfn1 = pfn_to_mfn(page_to_pfn(vec1->bv_page));
	unsigned long mfn2 = pfn_to_mfn(page_to_pfn(vec2->bv_page));

	return (mfn1 == mfn2) || ((mfn1 + 1) == mfn2);
}

static int failures;

static void check(const char *name, bool got, bool want)
{
	if (got != want) {
		printf("FAIL %-52s got=%d want=%d\n", name, got, want);
		failures++;
	} else {
		printf("PASS %-52s value=%d\n", name, got);
	}
}

int main(void)
{
	struct page pg1 = { .pfn = 1 }, pg2 = { .pfn = 2 }, pg3 = { .pfn = 3 };
	struct bio_vec a, b;

	/* pfn 1 -> mfn 10, pfn 2 -> mfn 11, pfn 3 -> mfn 10 (grant alias). */
	mfn_table[1] = 10;
	mfn_table[2] = 11;
	mfn_table[3] = 10;

	/* T1 legitimate: full page at mfn 10 followed by frame mfn 11. */
	a = (struct bio_vec){ .bv_page = &pg1, .bv_len = 4096, .bv_offset = 0 };
	b = (struct bio_vec){ .bv_page = &pg2, .bv_len = 512,  .bv_offset = 0 };
	printf("T1 old=%d new=%d\n", old_mergeable(&a, &b),
	       xen_biovec_phys_mergeable(&a, &b));
	check("T1 full-page adjacency allowed", xen_biovec_phys_mergeable(&a, &b), true);

	/* T2 negative (original bug): vec1 only 512 bytes into mfn 10, vec2 is a
	 * different frame mfn 11; old code merges because mfn1+1 == mfn2.
	 */
	a = (struct bio_vec){ .bv_page = &pg1, .bv_len = 512,  .bv_offset = 0 };
	b = (struct bio_vec){ .bv_page = &pg2, .bv_len = 4096, .bv_offset = 0 };
	printf("T2 old=%d new=%d\n", old_mergeable(&a, &b),
	       xen_biovec_phys_mergeable(&a, &b));
	check("T2 partial-page adjacency rejected", xen_biovec_phys_mergeable(&a, &b), false);
	check("T2 negative path triggers old bug (old=true)", old_mergeable(&a, &b), true);

	/* T3 negative (original bug): two grants map different pfns to the same
	 * mfn 10; old code merges because mfn1 == mfn2, extending past the page.
	 */
	a = (struct bio_vec){ .bv_page = &pg1, .bv_len = 4096, .bv_offset = 0 };
	b = (struct bio_vec){ .bv_page = &pg3, .bv_len = 4096, .bv_offset = 0 };
	printf("T3 old=%d new=%d\n", old_mergeable(&a, &b),
	       xen_biovec_phys_mergeable(&a, &b));
	check("T3 same-mfn grant alias rejected", xen_biovec_phys_mergeable(&a, &b), false);
	check("T3 negative path triggers old bug (old=true)", old_mergeable(&a, &b), true);

	/* T4 legitimate: two contiguous vectors inside the same machine frame. */
	a = (struct bio_vec){ .bv_page = &pg1, .bv_len = 512, .bv_offset = 0 };
	b = (struct bio_vec){ .bv_page = &pg1, .bv_len = 512, .bv_offset = 512 };
	printf("T4 old=%d new=%d\n", old_mergeable(&a, &b),
	       xen_biovec_phys_mergeable(&a, &b));
	check("T4 within-frame contiguity allowed", xen_biovec_phys_mergeable(&a, &b), true);

	if (failures) {
		printf("RESULT: %d check(s) failed\n", failures);
		return 1;
	}
	printf("RESULT: all checks passed\n");
	return 0;
}

